const repo="github-GoogleCloudPlatform-microservices-demo-1ae34901"; store("repo",repo);
function decode(r){return r.structuredContent ?? JSON.parse(r.content.find(x=>x.type==="text").text)}
const rs=await Promise.allSettled([
tools.mcp__truthgraph_test_customer__truthgraph_index_status({repositoryId:repo}),
tools.mcp__truthgraph_test_customer__truthgraph_search({repositoryId:repo,q:"checkout PlaceOrder handler",mode:"hybrid",limit:4,view:"files"})
]); for(let i=0;i<rs.length;i++){const r=rs[i]; if(r.status!=="fulfilled"){text({i,error:String(r.reason)});continue} store("tg"+i,r.value); text({i,value:decode(r.value)});}

