   287	
   288	func (cs *checkoutService) prepareOrderItemsAndShippingQuoteFromCart(ctx context.Context, userID, userCurrency string, address *pb.Address) (orderPrep, error) {
   289		var out orderPrep
   290		cartItems, err := cs.getUserCart(ctx, userID)
   291		if err != nil {
   292			return out, fmt.Errorf("cart failure: %+v", err)
   293		}
   294		orderItems, err := cs.prepOrderItems(ctx, cartItems, userCurrency)
   295		if err != nil {
   296			return out, fmt.Errorf("failed to prepare order: %+v", err)
   297		}
   298		shippingUSD, err := cs.quoteShipping(ctx, address, cartItems)
   299		if err != nil {
   300			return out, fmt.Errorf("shipping quote failure: %+v", err)
   301		}
   302		shippingPrice, err := cs.convertCurrency(ctx, shippingUSD, userCurrency)
   303		if err != nil {
   304			return out, fmt.Errorf("failed to convert shipping cost to currency: %+v", err)
   305		}
   306	
   307		out.shippingCostLocalized = shippingPrice
   308		out.cartItems = cartItems
   309		out.orderItems = orderItems
   310		return out, nil
   311	}
   312	
   313	func (cs *checkoutService) quoteShipping(ctx context.Context, address *pb.Address, items []*pb.CartItem) (*pb.Money, error) {
   314		shippingQuote, err := pb.NewShippingServiceClient(cs.shippingSvcConn).
   315			GetQuote(ctx, &pb.GetQuoteRequest{
   316				Address: address,
   317				Items:   items})
   318		if err != nil {
   319			return nil, fmt.Errorf("failed to get shipping quote: %+v", err)
   320		}
   321		return shippingQuote.GetCostUsd(), nil
   322	}
   323	
   324	func (cs *checkoutService) getUserCart(ctx context.Context, userID string) ([]*pb.CartItem, error) {
   325		cart, err := pb.NewCartServiceClient(cs.cartSvcConn).GetCart(ctx, &pb.GetCartRequest{UserId: userID})
   326		if err != nil {
   327			return nil, fmt.Errorf("failed to get user cart during checkout: %+v", err)
   328		}
   329		return cart.GetItems(), nil
   330	}
   331	
   332	func (cs *checkoutService) emptyUserCart(ctx context.Context, userID string) error {
   333		if _, err := pb.NewCartServiceClient(cs.cartSvcConn).EmptyCart(ctx, &pb.EmptyCartRequest{UserId: userID}); err != nil {
   334			return fmt.Errorf("failed to empty user cart during checkout: %+v", err)
   335		}
   336		return nil
   337	}
   338	
   339	func (cs *checkoutService) prepOrderItems(ctx context.Context, items []*pb.CartItem, userCurrency string) ([]*pb.OrderItem, error) {
   340		out := make([]*pb.OrderItem, len(items))
   341		cl := pb.NewProductCatalogServiceClient(cs.productCatalogSvcConn)
   342	
   343		for i, item := range items {
   344			product, err := cl.GetProduct(ctx, &pb.GetProductRequest{Id: item.GetProductId()})
   345			if err != nil {
   346				return nil, fmt.Errorf("failed to get product #%q", item.GetProductId())
   347			}
   348			price, err := cs.convertCurrency(ctx, product.GetPriceUsd(), userCurrency)
   349			if err != nil {
   350				return nil, fmt.Errorf("failed to convert price of %q to %s", item.GetProductId(), userCurrency)
   351			}
   352			out[i] = &pb.OrderItem{
   353				Item: item,
   354				Cost: price}
   355		}
   356		return out, nil
   357	}
   358	
   359	func (cs *checkoutService) convertCurrency(ctx context.Context, from *pb.Money, toCurrency string) (*pb.Money, error) {
   360		result, err := pb.NewCurrencyServiceClient(cs.currencySvcConn).Convert(context.TODO(), &pb.CurrencyConversionRequest{
   361			From:   from,
   362			ToCode: toCurrency})
   363		if err != nil {
   364			return nil, fmt.Errorf("failed to convert currency: %+v", err)
   365		}
   366		return result, err
   367	}
   368	
   369	func (cs *checkoutService) chargeCard(ctx context.Context, amount *pb.Money, paymentInfo *pb.CreditCardInfo) (string, error) {
   370		paymentResp, err := pb.NewPaymentServiceClient(cs.paymentSvcConn).Charge(ctx, &pb.ChargeRequest{
   371			Amount:     amount,
   372			CreditCard: paymentInfo})
